#!/usr/bin/env python3
"""
Homicide worldwide, sixth patch (culprits), 18 October 2026. Needs the fifth.

Renames the stand_your_ground row and rewrites one sentence of its note so they
name every part of the world the map now covers (Mexico's and Nigeria's states
and the other parts with their own criminal law), in map/app.js and
pipeline/sitemaps/registry.json.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTE = "## Homicide worldwide, sixth patch (18 October, the homicide and stand-your-ground chat)\n\nNeeds the fifth homicide patch (guards on its heading). Not a numbered round;\nthis note goes at the end of this file. No tiles patch. No app.js?v= bump.\nApply after the 402-place stand_your_ground.html (18 October) is in the maps\nrepo.\n\n- The stand_your_ground row's name and note now say the map covers every\n  country and territory and every part with its own criminal law: the US\n  states and territories, Mexico's 32 states, Australia's states and\n  territories, Nigeria's 36 states and the FCT, Bosnia's two entities and\n  Brcko, Micronesia's four states, Scotland and Northern Ireland, Iraqi\n  Kurdistan, Bougainville, Puntland, Aceh, the West Bank and Gaza, and\n  Zanzibar. The same name in pipeline/sitemaps/registry.json. No test change:\n  the round 5 tests check the row's id, route and place, not its name.\n"

DIFF = ''


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("homicide6: run from the culprits repository root")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if "## Homicide worldwide, fifth patch" not in text:
        sys.exit("homicide6: the fifth homicide patch must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("homicide6: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "pipeline/sitemaps/registry.json", check=False)
            sys.exit("homicide6: the diff did not apply:\n" + r.stdout + r.stderr)
        print("homicide6: applied")
    if NOTE.split("\n", 1)[0] not in text:
        h.write_text(text.rstrip("\n") + "\n\n\n" + NOTE, encoding="utf-8")


if __name__ == "__main__":
    main()
